"use client";

import { useState } from 'react';

const QuoteWidget = ({ actionProvider, setState, state }) => {
  const [step, setStep] = useState(1);
  const [formData, setFormData] = useState({
    weight: '',
    length: '',
    width: '',
    height: '',
    origin: '',
    destination: '',
    speed: 'standard'
  });
  const [quote, setQuote] = useState(null);
  const [loading, setLoading] = useState(false);

  const handleNext = () => {
    if (step < 3) setStep(step + 1);
  };

  const handleBack = () => {
    if (step > 1) setStep(step - 1);
  };

  const handleSubmit = async () => {
    setLoading(true);
    
    setTimeout(() => {
      const baseRate = Math.random() * 50 + 20;
      const fuel = baseRate * 0.15;
      const duties = baseRate * 0.12;
      const vat = (baseRate + duties) * 0.20;
      const total = baseRate + fuel + duties + vat;
      
      setQuote({
        baseRate: baseRate.toFixed(2),
        fuel: fuel.toFixed(2),
        duties: duties.toFixed(2),
        vat: vat.toFixed(2),
        total: total.toFixed(2)
      });
      setLoading(false);
    }, 1500);
  };

  const isStepValid = () => {
    if (step === 1) return formData.weight && formData.length && formData.width && formData.height;
    if (step === 2) return formData.origin && formData.destination;
    return true;
  };

  if (quote) {
    return (
      <div className="bg-white rounded-xl border p-4 mt-4 max-w-md">
        <div className="text-center">
          <div className="text-2xl mb-2">📦</div>
          <h3 className="font-bold text-gray-900 mb-2">Your Quote</h3>
          <p className="text-sm text-gray-600 mb-4">From {formData.origin} to {formData.destination}</p>
          
          <div className="bg-blue-50 rounded-lg p-4 mb-4">
            <div className="text-2xl font-bold text-blue-600 mb-1">£{quote.total}</div>
            <p className="text-sm text-gray-700">Total cost including all fees</p>
          </div>

          <div className="space-y-2 text-left text-sm mb-4">
            <div className="flex justify-between">
              <span>Base shipping</span>
              <span>£{quote.baseRate}</span>
            </div>
            <div className="flex justify-between">
              <span>Fuel surcharge</span>
              <span>£{quote.fuel}</span>
            </div>
            <div className="flex justify-between">
              <span>Import duties</span>
              <span>£{quote.duties}</span>
            </div>
            <div className="flex justify-between border-t pt-2">
              <span>VAT (20%)</span>
              <span>£{quote.vat}</span>
            </div>
          </div>

          <div className="flex gap-2">
            <button
              onClick={() => {setQuote(null); setStep(1); setFormData({weight: '', length: '', width: '', height: '', origin: '', destination: '', speed: 'standard'});}}
              className="flex-1 px-3 py-2 border border-gray-300 text-gray-700 text-sm rounded-lg hover:bg-gray-50"
            >
              New Quote
            </button>
            <button className="flex-1 px-3 py-2 bg-blue-600 text-white text-sm rounded-lg hover:bg-blue-700">
              Book Now
            </button>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="bg-white rounded-xl border p-4 mt-4 max-w-md">
      {/* Progress indicator */}
      <div className="flex items-center justify-center mb-4">
        <div className="flex items-center space-x-2">
          {[1, 2, 3].map((i) => (
            <div key={i} className="flex items-center">
              <div className={`w-6 h-6 rounded-full flex items-center justify-center text-xs font-medium ${
                i <= step ? 'bg-blue-600 text-white' : 'bg-gray-200 text-gray-600'
              }`}>
                {i}
              </div>
              {i < 3 && <div className={`w-8 h-0.5 ${i < step ? 'bg-blue-600' : 'bg-gray-200'}`} />}
            </div>
          ))}
        </div>
      </div>

      <div className="text-center mb-4">
        <h3 className="font-bold text-gray-900 mb-1">
          {step === 1 && "Package Details"}
          {step === 2 && "Shipping Route"}
          {step === 3 && "Service Speed"}
        </h3>
        <p className="text-sm text-gray-600">
          {step === 1 && "Enter your package dimensions"}
          {step === 2 && "Where are you shipping?"}
          {step === 3 && "Choose delivery speed"}
        </p>
      </div>

      {/* Step 1: Package Details */}
      {step === 1 && (
        <div className="space-y-3">
          <div className="grid grid-cols-2 gap-2">
            <div>
              <label className="block text-xs font-medium text-gray-700 mb-1">Weight (kg)</label>
              <input
                type="number"
                placeholder="2.5"
                className="w-full border border-gray-300 rounded-lg px-3 py-2 text-sm text-gray-900 focus:ring-1 focus:ring-blue-500"
                value={formData.weight}
                onChange={(e) => setFormData({...formData, weight: e.target.value})}
              />
            </div>
            <div>
              <label className="block text-xs font-medium text-gray-700 mb-1">Length (cm)</label>
              <input
                type="number"
                placeholder="30"
                className="w-full border border-gray-300 rounded-lg px-3 py-2 text-sm text-gray-900 focus:ring-1 focus:ring-blue-500"
                value={formData.length}
                onChange={(e) => setFormData({...formData, length: e.target.value})}
              />
            </div>
            <div>
              <label className="block text-xs font-medium text-gray-700 mb-1">Width (cm)</label>
              <input
                type="number"
                placeholder="20"
                className="w-full border border-gray-300 rounded-lg px-3 py-2 text-sm text-gray-900 focus:ring-1 focus:ring-blue-500"
                value={formData.width}
                onChange={(e) => setFormData({...formData, width: e.target.value})}
              />
            </div>
            <div>
              <label className="block text-xs font-medium text-gray-700 mb-1">Height (cm)</label>
              <input
                type="number"
                placeholder="15"
                className="w-full border border-gray-300 rounded-lg px-3 py-2 text-sm text-gray-900 focus:ring-1 focus:ring-blue-500"
                value={formData.height}
                onChange={(e) => setFormData({...formData, height: e.target.value})}
              />
            </div>
          </div>
        </div>
      )}

      {/* Step 2: Origin and Destination */}
      {step === 2 && (
        <div className="space-y-3">
          <div>
            <label className="block text-xs font-medium text-gray-700 mb-1">Ship from</label>
            <input
              type="text"
              placeholder="New York, United States"
              className="w-full border border-gray-300 rounded-lg px-3 py-2 text-sm text-gray-900 focus:ring-1 focus:ring-blue-500"
              value={formData.origin}
              onChange={(e) => setFormData({...formData, origin: e.target.value})}
            />
          </div>
          <div>
            <label className="block text-xs font-medium text-gray-700 mb-1">Ship to</label>
            <input
              type="text"
              placeholder="London, United Kingdom"
              className="w-full border border-gray-300 rounded-lg px-3 py-2 text-sm text-gray-900 focus:ring-1 focus:ring-blue-500"
              value={formData.destination}
              onChange={(e) => setFormData({...formData, destination: e.target.value})}
            />
          </div>
        </div>
      )}

      {/* Step 3: Shipping Speed */}
      {step === 3 && (
        <div className="space-y-2">
          {[
            { value: "standard", name: "Standard", time: "5-7 days", icon: "🚛" },
            { value: "express", name: "Express", time: "2-3 days", icon: "✈️" },
            { value: "overnight", name: "Overnight", time: "Next day", icon: "⚡" }
          ].map((option) => (
            <label key={option.value} className="block">
              <input
                type="radio"
                name="speed"
                value={option.value}
                checked={formData.speed === option.value}
                onChange={(e) => setFormData({...formData, speed: e.target.value})}
                className="sr-only"
              />
              <div className={`border rounded-lg p-3 cursor-pointer text-sm ${
                formData.speed === option.value 
                  ? 'border-blue-500 bg-blue-50' 
                  : 'border-gray-200 hover:border-gray-300'
              }`}>
                <div className="flex items-center justify-between">
                  <div className="flex items-center space-x-2">
                    <span>{option.icon}</span>
                    <div>
                      <div className="font-medium">{option.name}</div>
                      <div className="text-gray-600">{option.time}</div>
                    </div>
                  </div>
                </div>
              </div>
            </label>
          ))}
        </div>
      )}

      {/* Navigation buttons */}
      <div className="flex justify-between mt-4">
        <button
          onClick={handleBack}
          disabled={step === 1}
          className="px-4 py-2 text-sm text-gray-600 disabled:opacity-50 disabled:cursor-not-allowed"
        >
          ← Back
        </button>
        {step < 3 ? (
          <button
            onClick={handleNext}
            disabled={!isStepValid()}
            className="px-4 py-2 bg-blue-600 text-white text-sm rounded-lg hover:bg-blue-700 disabled:opacity-50 disabled:cursor-not-allowed"
          >
            Continue →
          </button>
        ) : (
          <button
            onClick={handleSubmit}
            disabled={loading}
            className="px-4 py-2 bg-blue-600 text-white text-sm rounded-lg hover:bg-blue-700 disabled:opacity-50"
          >
            {loading ? "Calculating..." : "Get Quote"}
          </button>
        )}
      </div>
    </div>
  );
};

export default QuoteWidget; 