"use client";

import { useState } from 'react';

const TrackingWidget = ({ actionProvider, setState, state }) => {
  const [trackingNumber, setTrackingNumber] = useState('');
  const [trackingResult, setTrackingResult] = useState(null);
  const [loading, setLoading] = useState(false);

  const handleTrack = async (e) => {
    e.preventDefault();
    if (!trackingNumber.trim()) return;
    
    setLoading(true);
    
    setTimeout(() => {
      setTrackingResult({
        status: "In Transit",
        location: "Distribution Center - Manchester, UK",
        estimatedDelivery: "Tomorrow by 6:00 PM",
        timeline: [
          { status: "Order Placed", date: "Dec 15, 2:30 PM", completed: true },
          { status: "Package Picked Up", date: "Dec 16, 9:15 AM", completed: true },
          { status: "In Transit", date: "Dec 17, 11:45 AM", completed: true },
          { status: "Out for Delivery", date: "Dec 18, Expected", completed: false },
          { status: "Delivered", date: "Dec 18, Expected", completed: false }
        ]
      });
      setLoading(false);
    }, 1000);
  };

  return (
    <div className="bg-white rounded-xl border p-4 mt-4 max-w-md">
      <div className="text-center mb-4">
        <div className="text-2xl mb-2">📍</div>
        <h3 className="font-bold text-gray-900 mb-1">Track Package</h3>
        <p className="text-sm text-gray-600">Enter your tracking number</p>
      </div>

      <form onSubmit={handleTrack} className="mb-4">
        <div className="flex gap-2">
          <input
            type="text"
            placeholder="1Z999AA1234567890"
            className="flex-1 border border-gray-300 rounded-lg px-3 py-2 text-sm text-gray-900 focus:ring-1 focus:ring-blue-500"
            value={trackingNumber}
            onChange={(e) => setTrackingNumber(e.target.value)}
          />
          <button
            type="submit"
            disabled={loading || !trackingNumber.trim()}
            className="px-4 py-2 bg-blue-600 text-white text-sm rounded-lg hover:bg-blue-700 disabled:opacity-50"
          >
            {loading ? "..." : "Track"}
          </button>
        </div>
      </form>

      {trackingResult && (
        <div className="space-y-4">
          <div className="text-center p-3 bg-green-50 rounded-lg">
            <div className="font-bold text-green-600 mb-1">{trackingResult.status}</div>
            <p className="text-green-800 text-sm mb-1">📍 {trackingResult.location}</p>
            <p className="text-xs text-green-700">Expected: {trackingResult.estimatedDelivery}</p>
          </div>
          
          <div className="space-y-3">
            <h4 className="font-medium text-gray-900 text-sm">Timeline:</h4>
            {trackingResult.timeline.map((event, index) => (
              <div key={index} className="flex items-start space-x-3">
                <div className={`w-3 h-3 rounded-full mt-1 ${event.completed ? 'bg-green-500' : 'bg-gray-300'}`} />
                <div className="flex-1">
                  <div className={`text-sm font-medium ${event.completed ? 'text-gray-900' : 'text-gray-600'}`}>
                    {event.status}
                  </div>
                  <div className={`text-xs ${event.completed ? 'text-gray-700' : 'text-gray-500'}`}>
                    {event.date}
                  </div>
                </div>
              </div>
            ))}
          </div>
          
          <button
            onClick={() => {setTrackingResult(null); setTrackingNumber('');}}
            className="w-full px-4 py-2 text-sm text-gray-600 border border-gray-300 rounded-lg hover:bg-gray-50"
          >
            Track Another Package
          </button>
        </div>
      )}
    </div>
  );
};

export default TrackingWidget; 