class MessageParser {
  constructor(actionProvider, state) {
    this.actionProvider = actionProvider;
    this.state = state;
  }

  parse(message) {
    const lowerCaseMessage = message.toLowerCase();

    // Quote-related keywords
    if (lowerCaseMessage.includes('quote') || 
        lowerCaseMessage.includes('price') || 
        lowerCaseMessage.includes('cost') || 
        lowerCaseMessage.includes('shipping rate') ||
        lowerCaseMessage.includes('how much')) {
      this.actionProvider.handleGetQuote();
      return;
    }

    // Tracking-related keywords
    if (lowerCaseMessage.includes('track') || 
        lowerCaseMessage.includes('where is') || 
        lowerCaseMessage.includes('status') ||
        lowerCaseMessage.includes('delivery') ||
        /\b[0-9]{10,}\b/.test(message)) { // Looks like tracking number
      this.actionProvider.handleTrackPackage();
      return;
    }

    // Duty/Tax questions
    if (lowerCaseMessage.includes('duty') || 
        lowerCaseMessage.includes('tax') || 
        lowerCaseMessage.includes('vat') ||
        lowerCaseMessage.includes('customs')) {
      this.actionProvider.handleDutyQuestion();
      return;
    }

    // Carrier questions
    if (lowerCaseMessage.includes('carrier') || 
        lowerCaseMessage.includes('ups') || 
        lowerCaseMessage.includes('fedex') ||
        lowerCaseMessage.includes('dhl') ||
        lowerCaseMessage.includes('usps')) {
      this.actionProvider.handleCarrierQuestion();
      return;
    }

    // Help or unclear input
    if (lowerCaseMessage.includes('help') || 
        lowerCaseMessage.includes('what can you do') ||
        lowerCaseMessage.includes('menu') ||
        lowerCaseMessage.includes('options')) {
      this.actionProvider.handleGeneralHelp();
      return;
    }

    // Default response for unrecognized input
    this.actionProvider.handleDefault();
  }
}

export default MessageParser; 